sys_variable_value.value:
(function execute(inputs, outputs) {

  var key = gs.getProperty("x_vuram_fcc_kyc_0.Veriff_SS");
  var Crypto = new HMAC_Generation().CryptoJS;
  var hash = Crypto.HmacSHA256(inputs.attempt_id ,key);
  outputs.attemptHmacKey = hash.toString(Crypto.enc.Hex);

})(inputs, outputs);

