sys_variable_value.value:
(function execute(inputs, outputs) {

    var session_decision = JSON.parse(inputs.parameter);
    
    
    outputs.media_id = session_decision.verification.attemptId;
    outputs.session_status = session_decision.verification.status;
    outputs.output_details = session_decision;
   

    var gr = new GlideRecord('x_vuram_financia_0_fcc_kyc_individual_details');
    if (gr.get(inputs.sys_parm)) { 
        gr.video_kyc_status = session_decision.verification.status;  
        gr.update();
    } else {
        gs.error('No record found with sys_id: ' + inputs.sys_parm);
    }

})(inputs, outputs);

